use bitops::{count_ones, reverse_bits, is_power_of_two, next_power_of_two};

#[test]
fn test_count_ones() {
    assert_eq!(count_ones(0), 0);
    assert_eq!(count_ones(1), 1);
    assert_eq!(count_ones(0b1011), 3);
    assert_eq!(count_ones(u32::MAX), 32);
}

#[test]
fn test_reverse_bits() {
    assert_eq!(reverse_bits(1u32), 1u32 << 31);
    assert_eq!(reverse_bits(1u32 << 31), 1u32);
    assert_eq!(reverse_bits(0u32), 0u32);
}

#[test]
fn test_is_power_of_two() {
    assert!(is_power_of_two(1));
    assert!(is_power_of_two(2));
    assert!(is_power_of_two(4));
    assert!(!is_power_of_two(0));
    assert!(!is_power_of_two(3));
    assert!(!is_power_of_two(6));
}

#[test]
fn test_next_power_of_two() {
    assert_eq!(next_power_of_two(1), 1);
    assert_eq!(next_power_of_two(3), 4);
    assert_eq!(next_power_of_two(4), 4);
    assert_eq!(next_power_of_two(5), 8);
}

#[test]
fn test_count_ones_pattern() {
    assert_eq!(count_ones(0b1010_1010), 4);
    assert_eq!(count_ones(0b1111_1111), 8);
}

